import { RuntimeBus } from "./RuntimeBus.ts";

// Helper engine to periodically emit runtime metrics

let coherence = 0.85;
let entropy = 0.12;
let activeWorkers = 0;
let eventsPerSecond = 0;
let eventCount = 0;

import { getConnectedClientCount } from "./WebSocketGateway.ts";

export function startTelemetryEngine() {
  
  // Track events emitted to calculate throughput
  RuntimeBus.on('*', () => {
    eventCount++;
  });

  // Main telemetry tick loop
  setInterval(() => {
    // Artificial sway for simulation
    const drift = (Math.random() - 0.5) * 0.02;
    coherence = Math.max(0, Math.min(1, coherence + drift + (entropy > 0.3 ? -0.05 : 0.01)));
    entropy = Math.max(0, Math.min(1, entropy + (Math.random() - 0.6) * 0.05));

    // Calculate throughput
    eventsPerSecond = eventCount;
    eventCount = 0;

    // Emit live stats
    RuntimeBus.emit("telemetry_update", {
      coherence,
      entropy,
      activeWorkers,
      connections: 0 // Could inject this from WS gateway
    });

    RuntimeBus.emit("coherence_update", { value: coherence });
    RuntimeBus.emit("entropy_update", { value: entropy });

    RuntimeBus.emit("runtime_health", {
      connections: getConnectedClientCount(),
      eventsPerSecond: eventsPerSecond
    });

  }, 1500);
}

// Interface for rings to register worker count changes
export function setWorkerCount(count: number) {
  activeWorkers = count;
  RuntimeBus.emit("ring_state_update", {
    state: {
      mode: count > 0 ? "executing" : "idle",
      activeWorkers
    }
  });
}
